                          const baseAmount = 100000;
                          const calculatedAmount = calculateIndexation(formula, baseAmount, indicesValues);
                          const variation = ((calculatedAmount - baseAmount) / baseAmount * 100).toFixed(2);
                          const isModified = formula.name.includes("Modifié") || formula.name.includes("Test");

                          return (
                            <div 
                              key={formula.id} 
                              className={`p-4 rounded-lg border ${
                                isModified ? 'border-blue-500 bg-blue-50' : 'border-gray-200'
                              }`}
                            >
                              <div className="space-y-2">
                                <div className="flex items-start justify-between">
                                  <h4 className="font-medium text-sm">
                                    {formula.name}
                                    {isModified && (
                                      <Badge variant="outline" className="ml-2 text-xs">
                                        Modifié
                                      </Badge>
                                    )}
                                  </h4>
                                </div>
                                <p className="text-xs text-muted-foreground font-mono">
                                  {formula.expression.substring(0, 50)}...
                                </p>
                                <div className="pt-2 border-t">
                                  <div className="flex justify-between items-baseline">
                                    <span className="text-sm text-muted-foreground">Montant calculé:</span>
                                    <span className="font-bold text-lg">
                                      {calculatedAmount.toLocaleString('fr-FR', { 
                                        style: 'currency', 
                                        currency: 'EUR' 
                                      })}
                                    </span>
                                  </div>
                                  <div className="flex justify-between items-baseline mt-1">
                                    <span className="text-sm text-muted-foreground">Variation:</span>
                                    <Badge 
                                      variant={parseFloat(variation) > 3 ? "destructive" : parseFloat(variation) > 2 ? "warning" : "secondary"}
                                      className="text-xs"
                                    >
                                      {variation > 0 ? '+' : ''}{variation}%
                                    </Badge>
                                  </div>
                                </div>
                              </div>
                            </div>
                          );
                        })}
