  reason: string;
  effectiveDate: Date;
  status: 'draft' | 'to_validate' | 'validated' | 'rejected';
  assignedValidator: string | null;
  lastUpdate: Date;
  requestedBy: string;
  createdAt: Date;
  validatedBy?: string | null;
  validatedAt?: Date | null;
  rejectionReason?: string | null;
  sla?: number; // heures restantes
  history?: Array<{
    id: string;
    action: string;
    date: Date;
    user: string;
    details?: string;
    traceId: string;
  }>;
  impact?: {
    lifecycle: string;
    deadlines: string;
    integrations: string;
  };
}

interface RoutingRule {
  id: string;
  name: string;
  businessUnit: string;
  threshold?: number;
  validator: string;
  substitute?: string;
  active: boolean;
}

interface NotificationTemplate {
  id: string;
  type: 'submitted' | 'validated' | 'rejected';
  channel: 'in-app' | 'email' | 'teams';
  template: string;
  active: boolean;
}

export default function Terminations() {
  const [activeView, setActiveView] = useState<'list' | 'history' | 'settings'>('list');
  const [statusFilter, setStatusFilter] = useState<string>("all");
