  const [showNewTerminationDialog, setShowNewTerminationDialog] = useState(false);
  const [showValidationModal, setShowValidationModal] = useState(false);
  const [showDetailPanel, setShowDetailPanel] = useState(false);
  const [currentStep, setCurrentStep] = useState(1);
  const [validationDecision, setValidationDecision] = useState<'validate' | 'reject'>('validate');
  const [rejectionReason, setRejectionReason] = useState("");
  const [showEmptyState, setShowEmptyState] = useState(false);
  const [showError, setShowError] = useState<string | null>(null);

  // Settings states
  const [slaEnabled, setSlaEnabled] = useState(true);
  const [slaHours, setSlaHours] = useState(24);
  const [autoReminders, setAutoReminders] = useState(true);
  const [sapSync, setSapSync] = useState(true);

  // New termination form data
  const [newTermination, setNewTermination] = useState({
    contractId: "",
    contractNumber: "",
    contractTitle: "",
    effectiveDate: "",
