      requestedBy: "Pierre Durand",
      createdAt: new Date("2024-01-10"),
      validatedBy: "Sophie Bernard",
      validatedAt: new Date("2024-01-15"),
      impact: {
        lifecycle: "Contrat résilié avec effet au 30/06/2024",
