      validatedAt: new Date("2024-02-05"),
      rejectionReason: "Date d'effet antérieure au délai de préavis contractuel"
    }
  ];

  // Routing rules mock data
  const routingRules: RoutingRule[] = [
    {
      id: "rule-1",
