      businessUnit: "BU International",
      validator: "Marie Dupont",
      substitute: "Pierre Durand",
      active: true
    }
  ];

  // Notification templates mock data
  const notificationTemplates: NotificationTemplate[] = [
    {
      id: "notif-1",
