                          <SelectContent>
                            <SelectItem value="all">Tous les statuts</SelectItem>
                            <SelectItem value="draft">Brouillon</SelectItem>
                            <SelectItem value="to_validate">À valider</SelectItem>
                            <SelectItem value="validated">Validée</SelectItem>
                            <SelectItem value="rejected">Rejetée</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>

                      <div>
                        <Label htmlFor="search" className="text-sm font-medium mb-1">Recherche</Label>
                        <div className="relative">
                          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                          <Input
                            id="search"
                            type="text"
                            placeholder="ID résiliation, mot-clé du motif..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-10"
                          />
                        </div>
                      </div>
                    </div>

                    <div className="flex justify-between items-center">
                      <div className="flex gap-2">
                        <Input
                          type="text"
                          placeholder="Contrat (N° + intitulé)"
                          className="w-48"
                        />
                        <Input
                          type="text"
                          placeholder="Demandeur"
                          className="w-40"
                        />
                        <Input
                          type="text"
                          placeholder="Valideur assigné"
                          className="w-40"
                        />
                      </div>
                      <div className="flex gap-2">
                        <Button 
                          onClick={() => setShowNewTerminationDialog(true)}
                          data-testid="button-create-termination"
                        >
                          <Plus className="w-4 h-4 mr-2" />
                          Créer une demande
                        </Button>
                        <Button variant="outline">
                          <FileDown className="w-4 h-4 mr-2" />
                          Exporter
                        </Button>
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {/* Terminations List Table - RE-1 */}
                {filteredTerminations.length === 0 && showEmptyState ? (
                  <Card>
                    <CardContent className="p-12 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                      <h3 className="text-lg font-medium text-gray-900 mb-2">Aucune demande</h3>
                      <p className="text-gray-500">Aucune demande ne correspond à vos filtres.</p>
                      <Button 
                        variant="outline" 
                        className="mt-4"
                        onClick={() => {
                          setStatusFilter('all');
                          setSearchQuery('');
                        }}
                      >
                        Réinitialiser les filtres
                      </Button>
                    </CardContent>
                  </Card>
                ) : (
                  <Card>
                    <CardContent className="p-0">
                      <div className="overflow-x-auto">
                        <Table>
                          <TableHeader>
                            <TableRow>
                              <TableHead>ID demande</TableHead>
                              <TableHead>Contrat</TableHead>
                              <TableHead>Motif (extrait)</TableHead>
                              <TableHead>Date d'effet</TableHead>
                              <TableHead>Statut</TableHead>
                              <TableHead>Valideur assigné</TableHead>
                              <TableHead>Dernière MàJ</TableHead>
                              <TableHead>Actions</TableHead>
                            </TableRow>
                          </TableHeader>
                          <TableBody>
                            {filteredTerminations.map((termination) => (
                              <TableRow key={termination.id} data-testid={`row-termination-${termination.id}`}>
                                <TableCell>
                                  <button 
                                    className="text-primary hover:underline font-medium"
                                    onClick={() => {
                                      setSelectedTermination(termination);
                                      setShowDetailPanel(true);
                                    }}
                                  >
                                    {termination.id}
                                  </button>
                                </TableCell>
                                <TableCell>
                                  <div>
                                    <div className="font-medium">{termination.contractNumber}</div>
                                    <div className="text-sm text-gray-500">{termination.contractTitle}</div>
                                  </div>
                                </TableCell>
                                <TableCell>
                                  <div className="max-w-xs truncate" title={termination.reason}>
                                    {termination.reason.substring(0, 50)}...
                                  </div>
                                </TableCell>
                                <TableCell>{formatDate(termination.effectiveDate)}</TableCell>
                                <TableCell>
                                  <div className="flex items-center gap-2">
                                    <StatusBadge
                                      variant={getStatusVariant(termination.status)}
                                      text={getStatusLabel(termination.status)}
                                    />
                                    {termination.sla && termination.sla < 24 && (
                                      <Badge variant="warning" className="text-xs">
                                        <Timer className="w-3 h-3 mr-1" />
                                        {termination.sla}h
                                      </Badge>
                                    )}
                                  </div>
                                </TableCell>
                                <TableCell>{termination.assignedValidator || '-'}</TableCell>
                                <TableCell>{formatDate(termination.lastUpdate)}</TableCell>
                                <TableCell>
                                  <div className="flex items-center gap-1">
                                    <Button 
                                      variant="ghost" 
                                      size="sm"
                                      onClick={() => {
                                        setSelectedTermination(termination);
                                        setShowDetailPanel(true);
                                      }}
                                      data-testid={`button-view-termination-${termination.id}`}
                                    >
                                      <Eye className="w-4 h-4" />
                                    </Button>
                                    {termination.status === 'to_validate' && (
                                      <>
                                        <Button 
                                          variant="ghost" 
                                          size="sm" 
                                          className="text-green-600 hover:text-green-700"
                                          onClick={() => {
                                            setSelectedTermination(termination);
                                            setShowValidationModal(true);
                                            setValidationDecision('validate');
                                          }}
                                        >
                                          <Check className="w-4 h-4" />
                                        </Button>
                                        <Button 
                                          variant="ghost" 
                                          size="sm" 
                                          className="text-red-600 hover:text-red-700"
                                          onClick={() => {
                                            setSelectedTermination(termination);
                                            setShowValidationModal(true);
                                            setValidationDecision('reject');
                                          }}
                                        >
                                          <X className="w-4 h-4" />
                                        </Button>
                                      </>
                                    )}
                                  </div>
                                </TableCell>
                              </TableRow>
                            ))}
