                      <div>Titre: Maintenance informatique</div>
                      <div>Statut: <Badge variant="success">Actif</Badge></div>
                      <div>Dates: 01/01/2024 - 31/12/2024</div>
                    </div>
                  </CardContent>
                </Card>
