                        <Alert className="border-amber-200 bg-amber-50">
                          <Timer className="h-4 w-4 text-amber-600" />
                          <AlertDescription className="text-sm">
                            Relance automatique dans {selectedTermination.sla} heures
                          </AlertDescription>
