import { useState } from "react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { cn } from "@/lib/utils";
import {
  Menu,
  ChevronDown,
  ChevronRight,
  LayoutDashboard,
  FileText,
  GitBranch,
  Calendar,
  TrendingUp,
