import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import {
  Search,
  Filter,
  Plus,
  Eye,
  Edit,
  FileText,
  Calendar,
  AlertCircle,
  Check,
  X,
  ChevronRight
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Textarea } from "@/components/ui/textarea";
import { AdminLayout } from "./AdminLayout";
import { queryClient } from "@/lib/queryClient";
import { apiRequest } from "@/lib/queryClient";
import { toast } from "@/hooks/use-toast";

const contractTypes = [
  { value: "OMSA", label: "OMSA" },
  { value: "LTSA", label: "LTSA" },
  { value: "OMGC", label: "OMGC" },
  { value: "Bail", label: "Bail" }
];

const indexationFormulas = [
  { value: "none", label: "Pas d'indexation" },
  { value: "ICHT", label: "P = P₀ × (ICHTREV / ICHT₀)" },
  { value: "ICHT_FMOA", label: "P = P₀ × (0,15 + 0,55 × (ICHTREV/ICHT₀) + 0,3 × (FMOAREV/FMOA₀))" },
  { value: "CPI", label: "P = P₋₁ × (1 + CPI)" },
  { value: "custom", label: "Formule personnalisée" }
];

const contractSchema = z.object({
  title: z.string().min(1, "Le titre est obligatoire"),
  type: z.enum(["OMSA", "LTSA", "OMGC", "Bail"]),
  technology: z.enum(["eolien", "PV"]).optional(),
  maintenanceProvider: z.string().optional(),
  numberOfTurbines: z.number().optional(),
  pricePerMWh: z.number().optional(),
  status: z.string(),
  startDate: z.string().min(1, "La date de début est obligatoire"),
  endDate: z.string().optional(),
  fixedAmount: z.number().min(0, "Le montant fixe est obligatoire"),
  variableAmount: z.number().min(0).optional(),
  billingPeriodicity: z.enum(["mensuelle", "trimestrielle", "semestrielle", "annuelle"]),
  paymentType: z.string().default("virement"),
  indexationFormula: z.string(),
  indexationDate: z.string().optional(),
  originalIndexDate: z.string().optional(),
  originalIndexValue: z.number().optional(),
  revisionIndexDate: z.string().optional(),
  indices: z.array(z.object({
    code: z.string(),
    originalDate: z.string().optional(),
    originalValue: z.number().optional(),
    revisionDate: z.string().optional()
  })).optional()
});

type ContractFormData = z.infer<typeof contractSchema>;

export function AdminContracts() {
  const [selectedContract, setSelectedContract] = useState<any>(null);
  const [showContractForm, setShowContractForm] = useState(false);
  const [filters, setFilters] = useState({
    type: "",
    status: "",
    businessUnit: "",
    search: ""
  });

  const { data: contracts, isLoading } = useQuery({
    queryKey: ["/api/admin/contracts", filters]
  });

  const form = useForm<ContractFormData>({
    resolver: zodResolver(contractSchema),
    defaultValues: {
      status: "draft",
      billingPeriodicity: "trimestrielle",
      paymentType: "virement",
      indexationFormula: "none",
      fixedAmount: 0,
      variableAmount: 0
    }
  });

  const contractType = form.watch("type");
  const indexationFormula = form.watch("indexationFormula");

  const createContractMutation = useMutation({
    mutationFn: (data: ContractFormData) => 
      apiRequest("/api/admin/contracts", {
        method: "POST",
        body: JSON.stringify(data)
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/contracts"] });
      setShowContractForm(false);
      form.reset();
      toast({
        title: "Contrat créé",
        description: "Le contrat a été créé avec succès et envoyé en validation"
      });
    }
  });

  const handleCreateContract = (data: ContractFormData) => {
    createContractMutation.mutate(data);
  };

  const getDeadlineInfo = (contract: any) => {
    if (!contract.nextDeadline) return null;
    const days = contract.daysUntilDeadline;
    const type = contract.deadlineType;

    return (
      <div className="flex items-center gap-2">
        <span className="text-sm">{type}</span>
        <Badge variant={days <= 7 ? "destructive" : days <= 30 ? "warning" : "secondary"}>
          J-{days}
        </Badge>
      </div>
    );
  };

  const resetFilters = () => {
    setFilters({
      type: "",
      status: "",
      businessUnit: "",
      search: ""
    });
  };

  const renderConditionalFields = () => {
    if (!contractType) return null;

    return (
      <>
        {/* Technology field for OMSA, LTSA, OMGC */}
        {["OMSA", "LTSA", "OMGC"].includes(contractType) && (
          <FormField
            control={form.control}
            name="technology"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Technologie *</FormLabel>
                <Select onValueChange={field.onChange} defaultValue={field.value}>
                  <FormControl>
                    <SelectTrigger>
                      <SelectValue placeholder="Sélectionner la technologie" />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    <SelectItem value="eolien">Éolien</SelectItem>
                    <SelectItem value="PV">Photovoltaïque</SelectItem>
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />
        )}

        {/* Maintenance provider for LTSA and OMGC */}
        {["LTSA", "OMGC"].includes(contractType) && (
          <FormField
            control={form.control}
            name="maintenanceProvider"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Nom du mainteneur (Contrat d'achat) *</FormLabel>
                <FormControl>
                  <Input {...field} placeholder="Ex: Bouygues, Engie..." />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
        )}

        {/* Number of turbines for OMSA */}
        {contractType === "OMSA" && (
          <FormField
            control={form.control}
            name="numberOfTurbines"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Nombre d'éoliennes</FormLabel>
                <FormControl>
                  <Input 
                    type="number" 
                    {...field} 
                    onChange={e => field.onChange(parseInt(e.target.value))}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
        )}

        {/* Fixed and variable amounts - Not for Bail */}
        {contractType !== "Bail" && (
          <>
            <FormField
              control={form.control}
              name="fixedAmount"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Montant fixe (€) *</FormLabel>
                  <FormControl>
                    <Input 
                      type="number" 
                      {...field}
                      onChange={e => field.onChange(parseFloat(e.target.value))}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="variableAmount"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Montant variable (€)</FormLabel>
                  <FormControl>
                    <Input 
                      type="number" 
                      {...field}
                      onChange={e => field.onChange(parseFloat(e.target.value))}
                      placeholder="0 si inexistant"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </>
        )}
      </>
    );
  };

  const renderIndexationFields = () => {
    if (indexationFormula === "none") return null;

    const needsMultipleIndices = ["ICHT_FMOA"].includes(indexationFormula);

    return (
      <>
        <FormField
          control={form.control}
          name="indexationDate"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Date d'indexation *</FormLabel>
              <FormControl>
                <Input type="date" {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        {needsMultipleIndices ? (
          <>
            <div className="space-y-4">
              <div className="border p-4 rounded-lg">
                <h4 className="font-medium mb-3">Indice ICHT</h4>
                <div className="grid grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="indices.0.originalDate"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Date d'origine</FormLabel>
                        <FormControl>
                          <Input type="date" {...field} />
                        </FormControl>
                        <FormDescription>Ou renseignez la valeur</FormDescription>
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="indices.0.originalValue"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Valeur d'origine</FormLabel>
                        <FormControl>
                          <Input 
                            type="number" 
                            {...field}
                            onChange={e => field.onChange(parseFloat(e.target.value))}
                          />
                        </FormControl>
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="indices.0.revisionDate"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Date de révision</FormLabel>
                        <FormControl>
                          <Input type="date" {...field} />
                        </FormControl>
                      </FormItem>
                    )}
                  />
                </div>
              </div>

              <div className="border p-4 rounded-lg">
                <h4 className="font-medium mb-3">Indice FMOA</h4>
                <div className="grid grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="indices.1.originalDate"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Date d'origine</FormLabel>
                        <FormControl>
                          <Input type="date" {...field} />
                        </FormControl>
                        <FormDescription>Ou renseignez la valeur</FormDescription>
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="indices.1.originalValue"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Valeur d'origine</FormLabel>
                        <FormControl>
                          <Input 
                            type="number" 
                            {...field}
                            onChange={e => field.onChange(parseFloat(e.target.value))}
                          />
                        </FormControl>
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="indices.1.revisionDate"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Date de révision</FormLabel>
                        <FormControl>
                          <Input type="date" {...field} />
                        </FormControl>
                      </FormItem>
                    )}
                  />
                </div>
              </div>
            </div>
          </>
        ) : (
          <div className="grid grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="originalIndexDate"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Date de l'indice d'origine</FormLabel>
                  <FormControl>
                    <Input type="date" {...field} />
                  </FormControl>
                  <FormDescription>Un seul champ requis (date ou valeur)</FormDescription>
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="originalIndexValue"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Valeur de l'indice d'origine</FormLabel>
                  <FormControl>
                    <Input 
                      type="number" 
                      {...field}
                      onChange={e => field.onChange(parseFloat(e.target.value))}
                    />
                  </FormControl>
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="revisionIndexDate"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Date de révision de l'indice</FormLabel>
                  <FormControl>
                    <Input type="date" {...field} />
                  </FormControl>
                </FormItem>
              )}
            />
          </div>
        )}
      </>
    );
  };

  return (
    <AdminLayout>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Gestion des contrats</h1>
            <p className="text-gray-600 mt-1">Administration et validation des contrats</p>
          </div>
          <Button onClick={() => setShowContractForm(true)}>
            <Plus className="h-4 w-4 mr-2" />
            Nouveau contrat
          </Button>
        </div>

        {/* Filters */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Filtres</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div>
                <Label>Type de contrat</Label>
                <Select 
                  value={filters.type} 
                  onValueChange={(value) => setFilters({...filters, type: value})}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Tous les types" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">Tous</SelectItem>
                    {contractTypes.map(type => (
                      <SelectItem key={type.value} value={type.value}>
                        {type.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label>Statut</Label>
                <Select 
                  value={filters.status} 
                  onValueChange={(value) => setFilters({...filters, status: value})}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Tous les statuts" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">Tous</SelectItem>
                    <SelectItem value="draft">Brouillon</SelectItem>
                    <SelectItem value="pending_validation">En validation</SelectItem>
                    <SelectItem value="active">Actif</SelectItem>
                    <SelectItem value="terminated">Résilié</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label>BU/Entité</Label>
                <Select 
                  value={filters.businessUnit} 
                  onValueChange={(value) => setFilters({...filters, businessUnit: value})}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Toutes les BU" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">Toutes</SelectItem>
                    <SelectItem value="ENGIE Solutions France">ENGIE Solutions France</SelectItem>
                    <SelectItem value="ENGIE Green">ENGIE Green</SelectItem>
                    <SelectItem value="ENGIE Global Energy Management">ENGIE Global Energy Management</SelectItem>
                    <SelectItem value="ENGIE Flex">ENGIE Flex</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label>Recherche</Label>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                  <Input 
                    placeholder="N° contrat, intitulé..." 
                    className="pl-10"
                    value={filters.search}
                    onChange={(e) => setFilters({...filters, search: e.target.value})}
                  />
                </div>
              </div>
            </div>

            <div className="flex justify-end gap-2 mt-4">
              <Button variant="outline" onClick={resetFilters}>
                Réinitialiser
              </Button>
              <Button>
                Enregistrer les filtres
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Contracts Table */}
        <Card>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>N°/Intitulé</TableHead>
                  <TableHead>Type</TableHead>
                  <TableHead>Statut</TableHead>
                  <TableHead>Périodicité</TableHead>
                  <TableHead>Date début/fin</TableHead>
                  <TableHead>Échéance à venir</TableHead>
                  <TableHead>Responsable</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {contracts?.map((contract: any) => (
                  <TableRow key={contract.id}>
                    <TableCell>
                      <div>
                        <p className="font-medium">{contract.number}</p>
                        <p className="text-sm text-gray-500">{contract.title}</p>
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">{contract.type}</Badge>
                    </TableCell>
                    <TableCell>
                      <Badge variant={
                        contract.status === "active" ? "success" :
                        contract.status === "pending_validation" ? "warning" :
                        "secondary"
                      }>
                        {contract.status === "pending_validation" ? "En validation" :
                         contract.status === "active" ? "Actif" :
                         contract.status === "draft" ? "Brouillon" :
                         "Résilié"}
                      </Badge>
                    </TableCell>
                    <TableCell>{contract.billingPeriodicity || "-"}</TableCell>
                    <TableCell>
                      <div className="text-sm">
                        <p>{new Date(contract.startDate).toLocaleDateString("fr-FR")}</p>
                        {contract.endDate && (
                          <p className="text-gray-500">
                            {new Date(contract.endDate).toLocaleDateString("fr-FR")}
                          </p>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>{getDeadlineInfo(contract)}</TableCell>
                    <TableCell>{contract.responsible || "-"}</TableCell>
                    <TableCell>
                      <div className="flex gap-2">
                        <Button 
                          size="sm" 
                          variant="outline"
                          onClick={() => setSelectedContract(contract)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button size="sm" variant="outline">
                          <Edit className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            {isLoading && (
              <div className="text-center py-8 text-gray-500">
                Chargement des contrats...
              </div>
            )}
            {!isLoading && (!contracts || contracts.length === 0) && (
              <div className="text-center py-8 text-gray-500">
                Aucun contrat trouvé
              </div>
            )}
          </CardContent>
        </Card>

        {/* Contract Creation Form Modal */}
        {showContractForm && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <Card className="w-full max-w-4xl max-h-[90vh] overflow-y-auto">
              <CardHeader>
                <CardTitle>Créer un nouveau contrat</CardTitle>
              </CardHeader>
              <CardContent>
                <Form {...form}>
                  <form onSubmit={form.handleSubmit(handleCreateContract)} className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <FormField
                        control={form.control}
                        name="title"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Titre (nom du contrat, nom SPV...) *</FormLabel>
                            <FormControl>
                              <Input {...field} placeholder="Ex: Fourniture électricité Lyon" />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="type"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Type de contrat *</FormLabel>
                            <Select onValueChange={field.onChange} defaultValue={field.value}>
                              <FormControl>
                                <SelectTrigger>
                                  <SelectValue placeholder="Sélectionner le type" />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {contractTypes.map(type => (
                                  <SelectItem key={type.value} value={type.value}>
                                    {type.label}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      {renderConditionalFields()}

                      <FormField
                        control={form.control}
                        name="status"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Statut du contrat *</FormLabel>
                            <Select onValueChange={field.onChange} defaultValue={field.value}>
                              <FormControl>
                                <SelectTrigger>
                                  <SelectValue />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                <SelectItem value="draft">Brouillon</SelectItem>
                                <SelectItem value="pending_validation">En validation</SelectItem>
                                <SelectItem value="active">Actif</SelectItem>
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="startDate"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Date de début *</FormLabel>
                            <FormControl>
                              <Input type="date" {...field} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="endDate"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Date de fin</FormLabel>
                            <FormControl>
                              <Input type="date" {...field} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="billingPeriodicity"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Périodicité des factures *</FormLabel>
                            <Select onValueChange={field.onChange} defaultValue={field.value}>
                              <FormControl>
                                <SelectTrigger>
                                  <SelectValue />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                <SelectItem value="mensuelle">Mensuelle</SelectItem>
                                <SelectItem value="trimestrielle">Trimestrielle</SelectItem>
                                <SelectItem value="semestrielle">Semestrielle</SelectItem>
                                <SelectItem value="annuelle">Annuelle</SelectItem>
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="indexationFormula"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Formule d'indexation</FormLabel>
                            <Select onValueChange={field.onChange} defaultValue={field.value}>
                              <FormControl>
                                <SelectTrigger>
                                  <SelectValue />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {indexationFormulas.map(formula => (
                                  <SelectItem key={formula.value} value={formula.value}>
                                    {formula.label}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>

                    {renderIndexationFields()}

                    <div className="flex justify-end gap-4">
                      <Button 
                        type="button" 
                        variant="outline"
                        onClick={() => {
                          setShowContractForm(false);
                          form.reset();
                        }}
                      >
                        Annuler
                      </Button>
                      <Button type="submit" disabled={createContractMutation.isPending}>
                        {createContractMutation.isPending ? "Création..." : "Créer et soumettre à validation"}
                      </Button>
                    </div>
                  </form>
                </Form>
              </CardContent>
            </Card>
          </div>
        )}
      </div>
    </AdminLayout>
  );
}

client/src/pages/admin/AdminDashboard.ts.content:
import { useQuery } from "@tanstack/react-query";
import {
  FileText,
  TrendingUp,
  FileEdit,
  AlertTriangle,
  Calendar,
  Clock,
  AlertCircle,
  FileWarning,
  Upload,
  CheckCircle,
  XCircle
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { AdminLayout } from "./AdminLayout";
import { Link } from "wouter";

interface KPI {
  label: string;
  value: number;
  icon: React.ComponentType<{ className?: string }>;
  color: string;
  link: string;
}

interface Alert {
  id: string;
  type: "critical" | "warning" | "info";
  title: string;
  message: string;
  timestamp: Date;
  isRead: boolean;
  referenceId?: string;
}

interface BlockedTask {
  id: string;
  type: string;
  reference: string;
  blockedSince: Date;
  priority: "high" | "medium" | "low";
  assignedTo: string;
}

interface IndexationReport {
  id: string;
  contractNumber: string;
  contractTitle: string;
  date: Date;
  status: "provisoire" | "validé" | "rejeté";
  variation: number;
}

export function AdminDashboard() {
  // Fetch KPIs
  const { data: kpis } = useQuery({
    queryKey: ["/api/admin/kpis"]
  });

  // Fetch alerts
  const { data: alerts } = useQuery({
    queryKey: ["/api/admin/alerts"],
    refetchInterval: 30000 // Refresh every 30 seconds
  });

  // Fetch blocked tasks
  const { data: blockedTasks } = useQuery({
    queryKey: ["/api/admin/blocked-tasks"]
  });

  // Fetch recent indexation reports
  const { data: recentReports } = useQuery({
    queryKey: ["/api/admin/recent-reports"]
  });

  const kpiCards: KPI[] = [
    {
      label: "Contrats à valider",
      value: kpis?.contractsToValidate || 0,
      icon: FileText,
      color: "text-blue-600",
      link: "/admin/contracts/validate"
    },
    {
      label: "Indexations à valider",
      value: kpis?.indexationsToValidate || 0,
      icon: TrendingUp,
      color: "text-green-600",
      link: "/admin/indexations/validate"
    },
    {
      label: "Avenants à valider",
      value: kpis?.amendmentsToValidate || 0,
      icon: FileEdit,
      color: "text-purple-600",
      link: "/admin/amendments/validate"
    },
    {
      label: "Résiliations en cours",
      value: kpis?.terminationsInProgress || 0,
      icon: XCircle,
      color: "text-red-600",
      link: "/admin/contracts/terminations"
    }
  ];

  const deadlineKpis = [
    { label: "J-30", value: kpis?.dueDatesJ30 || 0, color: "bg-yellow-100 text-yellow-800" },
    { label: "J-7", value: kpis?.dueDatesJ7 || 0, color: "bg-orange-100 text-orange-800" },
    { label: "J-1", value: kpis?.dueDatesJ1 || 0, color: "bg-red-100 text-red-800" }
  ];

  const technicalKpis = [
    { label: "Erreurs sources indices", value: kpis?.indexSourceErrors || 0, icon: AlertCircle },
    { label: "Envois SAP en erreur", value: kpis?.sapErrors || 0, icon: FileWarning }
  ];

  const getAlertIcon = (type: string) => {
    switch (type) {
      case "critical":
        return <AlertCircle className="h-4 w-4 text-red-500" />;
      case "warning":
        return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
      default:
        return <AlertCircle className="h-4 w-4 text-blue-500" />;
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "high":
        return "bg-red-100 text-red-800";
      case "medium":
        return "bg-yellow-100 text-yellow-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  return (
    <AdminLayout>
      <div className="space-y-6">
        {/* Page Title */}
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Administration — Vue globale</h1>
          <p className="text-gray-600 mt-1">Tableau de bord et supervision du système KLYXOR</p>
        </div>

        {/* KPI Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {kpiCards.map((kpi) => {
            const Icon = kpi.icon;
            return (
              <Link key={kpi.label} href={kpi.link}>
                <Card className="cursor-pointer hover:shadow-md transition-shadow">
                  <CardHeader className="flex flex-row items-center justify-between pb-2">
                    <CardTitle className="text-sm font-medium text-gray-600">
                      {kpi.label}
                    </CardTitle>
                    <Icon className={`h-4 w-4 ${kpi.color}`} />
                  </CardHeader>
                  <CardContent>
                    <div className="text-2xl font-bold">{kpi.value}</div>
                  </CardContent>
                </Card>
              </Link>
            );
          })}
        </div>

        {/* Deadline KPIs */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Calendar className="h-5 w-5" />
              Échéances à venir
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex gap-4">
              {deadlineKpis.map((deadline) => (
                <div key={deadline.label} className="flex-1">
                  <div className="text-center p-4 rounded-lg bg-gray-50">
                    <Badge className={deadline.color}>
                      {deadline.label}
                    </Badge>
                    <div className="text-2xl font-bold mt-2">{deadline.value}</div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Critical Alerts Widget */}
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle className="flex items-center gap-2">
                <AlertTriangle className="h-5 w-5 text-red-500" />
                Alertes critiques
              </CardTitle>
              <Link href="/admin/notifications">
                <Button variant="outline" size="sm">Voir tout</Button>
              </Link>
            </CardHeader>
            <CardContent>
              <ScrollArea className="h-[250px]">
                <div className="space-y-3">
                  {alerts?.slice(0, 5).map((alert: Alert) => (
                    <div
                      key={alert.id}
                      className={cn(
                        "p-3 rounded-lg border",
                        !alert.isRead ? "bg-yellow-50 border-yellow-200" : "bg-white"
                      )}
                    >
                      <div className="flex items-start gap-2">
                        {getAlertIcon(alert.type)}
                        <div className="flex-1">
                          <p className="font-medium text-sm">{alert.title}</p>
                          <p className="text-xs text-gray-600 mt-1">{alert.message}</p>
                          <p className="text-xs text-gray-400 mt-2">
                            {new Date(alert.timestamp).toLocaleString("fr-FR")}
                          </p>
                        </div>
                        {!alert.isRead && (
                          <Badge variant="outline" className="text-xs">Non lu</Badge>
                        )}
                      </div>
                    </div>
                  ))}
                  {(!alerts || alerts.length === 0) && (
                    <p className="text-center text-gray-500 py-4">Aucune alerte critique</p>
                  )}
                </div>
              </ScrollArea>
            </CardContent>
          </Card>

          {/* Blocked Tasks Widget */}
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle className="flex items-center gap-2">
                <Clock className="h-5 w-5 text-orange-500" />
                Tâches bloquantes ({">"} 24h)
              </CardTitle>
              <Link href="/admin/tasks">
                <Button variant="outline" size="sm">Voir tout</Button>
              </Link>
            </CardHeader>
            <CardContent>
              <ScrollArea className="h-[250px]">
                <div className="space-y-3">
                  {blockedTasks?.slice(0, 5).map((task: BlockedTask) => (
                    <div key={task.id} className="p-3 rounded-lg border bg-white">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <p className="font-medium text-sm">{task.type}</p>
                          <p className="text-xs text-gray-600 mt-1">{task.reference}</p>
                          <p className="text-xs text-gray-500 mt-2">
                            Assigné à: {task.assignedTo}
                          </p>
                        </div>
                        <div className="text-right">
                          <Badge className={getPriorityColor(task.priority)}>
                            {task.priority === "high" ? "Urgent" : 
                             task.priority === "medium" ? "Moyen" : "Faible"}
                          </Badge>
                          <p className="text-xs text-gray-500 mt-1">
                            Bloqué depuis {Math.floor((Date.now() - new Date(task.blockedSince).getTime()) / (1000 * 60 * 60))}h
                          </p>
                        </div>
                      </div>
                    </div>
                  ))}
                  {(!blockedTasks || blockedTasks.length === 0) && (
                    <p className="text-center text-gray-500 py-4">Aucune tâche bloquante</p>
                  )}
                </div>
              </ScrollArea>
            </CardContent>
          </Card>
        </div>

        {/* Technical KPIs */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {technicalKpis.map((kpi) => {
            const Icon = kpi.icon;
            return (
              <Card key={kpi.label}>
                <CardHeader className="flex flex-row items-center justify-between pb-2">
                  <CardTitle className="text-sm font-medium text-gray-600">
                    {kpi.label}
                  </CardTitle>
                  <Icon className="h-4 w-4 text-red-500" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-red-600">{kpi.value}</div>
                  <Button variant="outline" size="sm" className="mt-2">
                    Ouvrir journal technique
                  </Button>
                </CardContent>
              </Card>
            );
          })}
        </div>

        {/* Recent Indexation Reports */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5" />
              Derniers rapports d'indexation
            </CardTitle>
            <Link href="/admin/indexations/reports">
              <Button variant="outline" size="sm">Voir tout</Button>
            </Link>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b">
                    <th className="text-left py-2 text-sm font-medium text-gray-600">Contrat</th>
                    <th className="text-left py-2 text-sm font-medium text-gray-600">Date</th>
                    <th className="text-left py-2 text-sm font-medium text-gray-600">Statut</th>
                    <th className="text-left py-2 text-sm font-medium text-gray-600">Variation</th>
                    <th className="text-left py-2 text-sm font-medium text-gray-600">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {recentReports?.slice(0, 5).map((report: IndexationReport) => (
                    <tr key={report.id} className="border-b">
                      <td className="py-2">
                        <div>
                          <p className="text-sm font-medium">{report.contractNumber}</p>
                          <p className="text-xs text-gray-500">{report.contractTitle}</p>
                        </div>
                      </td>
                      <td className="py-2 text-sm">
                        {new Date(report.date).toLocaleDateString("fr-FR")}
                      </td>
                      <td className="py-2">
                        <Badge variant={
                          report.status === "validé" ? "success" :
                          report.status === "rejeté" ? "destructive" :
                          "secondary"
                        }>
                          {report.status}
                        </Badge>
                      </td>
                      <td className="py-2 text-sm">
                        <span className={report.variation > 0 ? "text-green-600" : "text-red-600"}>
                          {report.variation > 0 ? "+" : ""}{report.variation.toFixed(2)}%
                        </span>
                      </td>
                      <td className="py-2">
                        <div className="flex gap-2">
                          <Button size="sm" variant="outline">Voir</Button>
                          <Button size="sm" variant="outline">PDF</Button>
                          <Button size="sm" variant="outline">XLS</Button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {(!recentReports || recentReports.length === 0) && (
                <p className="text-center text-gray-500 py-4">Aucun rapport récent</p>
              )}
            </div>
          </CardContent>
        </Card>
      </div>
    </AdminLayout>
  );
}

function cn(...classes: (string | boolean | undefined)[]) {
  return classes.filter(Boolean).join(" ");
}

client/src/pages/admin/AdminIndexations..content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import {
  TrendingUp,
  Calculator,
  History,
  FileText,
  Search,
  RefreshCw,
  Check,
  X,
  Download,
  AlertCircle,
  Calendar
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { AdminLayout } from "./AdminLayout";
import { queryClient } from "@/lib/queryClient";
import { apiRequest } from "@/lib/queryClient";
import { toast } from "@/hooks/use-toast";

interface IndexationFormula {
  id: string;
  code: string;
  name: string;
  formula: string;
  description: string;
  indices: string[];
}

interface EconomicIndex {
  code: string;
  name: string;
  value: number;
  date: Date;
  source: string;
  status: "definitive" | "provisional";
}

interface Indexation {
  id: string;
  contractId: string;
  contractNumber: string;
  contractTitle: string;
  indexationDate: Date;
  formula: string;
  oldAmount: number;
  newAmount: number;
  variation: number;
  status: "to_calculate" | "pending" | "validated" | "rejected";
  indices: {
    code: string;
    valueN0: number;
    valueN: number;
  }[];
}

const formulas: IndexationFormula[] = [
  {
    id: "2A",
    code: "Type 2.A",
    name: "ICHT/FMOA sur base initiale",
    formula: "Montant_n = Montant_0 × (0,15 + 0,55 × (ICHT_rev/ICHT_0) + 0,3 × (FMOA_rev/FMOA_0))",
    description: "Indexation basée sur le montant initial avec indices ICHT et FMOA",
    indices: ["ICHT", "FMOA"]
  },
  {
    id: "2B",
    code: "Type 2.B",
    name: "ICHT/FMOA sur base précédente",
    formula: "Montant_n = Montant_{n-1} × (0,15 + 0,55 × (ICHT_rev/ICHT_0) + 0,3 × (FMOA_rev/FMOA_0))",
    description: "Indexation basée sur le montant précédent avec indices ICHT et FMOA",
    indices: ["ICHT", "FMOA"]
  },
  {
    id: "3",
    code: "Type 3",
    name: "CPI",
    formula: "Montant_n = Montant_0 × (1 + (CPI/CPI_0))",
