    indices: ["CPI"]
  },
  {
    id: "ICHT",
    code: "ICHT Simple",
    name: "ICHT seul",
    formula: "P = P₀ × (ICHTREV / ICHT₀)",
    description: "Indexation simple basée sur l'indice ICHT",
    indices: ["ICHT"]
  }
];

const testData = [
  {
    park: "PARC AUXERROIS",
    code: "AUX89",
