                      <TableCell>Indice du coût horaire du travail</TableCell>
                      <TableCell>117.8</TableCell>
                      <TableCell>01/09/2024</TableCell>
                      <TableCell>INSEE</TableCell>
                      <TableCell>
                        <Badge variant="success">Définitive</Badge>
                      </TableCell>
